{"content":"<!DOCTYPE html>
<html>
<head>
    <title>Paper Harbor</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        .product { border: 1px solid #ccc; padding: 10px; margin: 10px 0; }
        .cart-item { display: flex; justify-content: space-between; }
        .cart-total { font-weight: bold; margin-top: 10px; }
    </style>
</head>
<body>
    <h1>Paper Harbor</h1>
    <input type="text" id="search" placeholder="Search products...">
    <div id="filters">
        <label><input type="checkbox" id="all"> All</label>
        <label><input type="checkbox" id="stationery"> Stationery</label>
        <label><input type="checkbox" id="office"> Office</label>
        <label><input type="checkbox" id="art"> Art</label>
    </div>
    <div id="products"></div>
    <div id="cart" style="margin-top: 40px;">
        <h2>Cart</h2>
        <div id="cart-items"></div>
        <div class="cart-total" id="cart-total">Total: $0.00</div>
        <button onclick="checkout()">Checkout</button>
    </div>
    <script>
        const products = [
            { name: 'Notebook', price: 12.99, category: 'stationery' },
            { name: 'Pen Set', price: 8.49, category: 'stationery' },
            { name: 'Desk Organizer', price: 15.99, category: 'office' },
            { name: 'Art Supplies Kit', price: 22.99, category: 'art' },
            { name: 'Highlighter', price: 4.99, category: 'stationery' },
            { name: 'File Folder', price: 7.99, category: 'office' }
        ];

        let cart = JSON.parse(localStorage.getItem('cart')) || [];

        function updateCart() {
            const cartItems = document.getElementById('cart-items');
            cartItems.innerHTML = '';
            let total = 0;

            cart.forEach((item, index) => {
                const div = document.createElement('div');
                div.className = 'cart-item';
                div.innerHTML = `
                    <span>${item.name} - $${item.price.toFixed(2)} x ${item.quantity}</span>
                    <button onclick="removeFromCart(${index})">Remove</button>
                `;
                cartItems.appendChild(div);
                total += item.price * item.quantity;
            });

            document.getElementById('cart-total').textContent = `Total: $${total.toFixed(2)}`;
            localStorage.setItem('cart', JSON.stringify(cart));
        }

        function removeFromCart(index) {
            cart.splice(index, 1);
            updateCart();
        }

        function checkout() {
            const name = prompt('Enter your name:');
            const email = prompt('Enter your email:');
            if (name && email) {
                alert(`Thank you, ${name}! Your order is confirmed. We'll send a confirmation to ${email}.
                Your cart has been cleared.`);
                cart = [];
                updateCart();
            }
        }

        function filterProducts() {
            const search = document.getElementById('search').value.toLowerCase();
            const filters = {
                all: document.getElementById('all').checked,
                stationery: document.getElementById('stationery').checked,
                office: document.getElementById('office').checked,
                art: document.getElementById('art').checked
            };

            const filtered = products.filter(product => {
                const matchesSearch = product.name.toLowerCase().includes(search);
                const matchesCategory = filters.all || 
                    (filters.stationery && product.category === 'stationery') ||
                    (filters.office && product.category === 'office') ||
                    (filters.art && product.category === 'art');
                return matchesSearch && matchesCategory;
            });

            const productsDiv = document.getElementById('products');
            productsDiv.innerHTML = '';

            filtered.forEach(product => {
                const div = document.createElement('div');
                div.className = 'product';
                div.innerHTML = `
                    <h3>${product.name}</h3>
                    <p>$${product.price.toFixed(2)}</p>
                    <button onclick="addToCart('${product.name}', ${product.price})">Add to Cart</button>
                `;
                productsDiv.appendChild(div);
            });
        }

        function addToCart(name, price) {
            const existing = cart.find(item => item.name === name);
            if (existing) {
                existing.quantity++;
            } else {
                cart.push({ name, price, quantity: 1 });
            }
            updateCart();
        }

        // Initial update
        filterProducts();
        updateCart();
    </script>
</body>
</html>","path":"PaperHarbor/index.html"}
